-- Use the same confirmed WB Dacha direction for supplies and cartons.
DROP VIEW av2_supply_city_scopes;
--> statement-breakpoint
CREATE VIEW av2_supply_city_scopes AS SELECT id,market,store,destination,(WITH RECURSIVE city_chars(rest,normalized) AS (
    SELECT coalesce(destination,''),' '
    UNION ALL SELECT substr(rest,2),normalized||CASE
      WHEN instr('ABCDEFGHIJKLMNOPQRSTUVWXYZАБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ0123456789',substr(rest,1,1))>0 THEN substr(rest,1,1)
      WHEN instr('abcdefghijklmnopqrstuvwxyzабвгдеёжзийклмнопрстуфхцчшщъыьэюя0123456789',substr(rest,1,1))>0 THEN substr('ABCDEFGHIJKLMNOPQRSTUVWXYZАБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ0123456789',instr('abcdefghijklmnopqrstuvwxyzабвгдеёжзийклмнопрстуфхцчшщъыьэюя0123456789',substr(rest,1,1)),1)
      ELSE ' ' END FROM city_chars WHERE rest<>''
  ), city_name AS (SELECT normalized||' ' normalized FROM city_chars WHERE rest='')
  SELECT CASE WHEN market='WB' AND instr(normalized,' ДАЧА ')>0
      AND trim(replace(replace(replace(normalized,' ','<>'),'><',''),'<>',' ')) IN ('ДАЧА','ДАЧА 2','WB ДАЧА','WB ДАЧА 2','ВБ ДАЧА','ВБ ДАЧА 2','WILDBERRIES ДАЧА','WILDBERRIES ДАЧА 2')
      THEN 'DACHA' WHEN ((instr(normalized,' СПБ ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГ ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГ ')>0 OR instr(normalized,' САНКТПЕТЕРБУРГ ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГА ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГА ')>0 OR instr(normalized,' САНКТПЕТЕРБУРГА ')>0 OR instr(normalized,' ПИТЕР ')>0) + (instr(normalized,' МОСКВА ')>0 OR instr(normalized,' МОСКВЫ ')>0 OR instr(normalized,' МСК ')>0) + (instr(normalized,' ЕКБ ')>0 OR instr(normalized,' ЕКАТЕРИНБУРГ ')>0) + (instr(normalized,' НОВОСИБ ')>0 OR instr(normalized,' НОВОСИБИРСК ')>0) + (instr(normalized,' КАЗАНЬ ')>0 OR instr(normalized,' КАЗАНИ ')>0) + (instr(normalized,' РОСТОВ ')>0 OR instr(normalized,' РОСТОВА ')>0) + (instr(normalized,' КОСТРОМА ')>0 OR instr(normalized,' КОСТРОМЫ ')>0))=1 THEN CASE WHEN (instr(normalized,' СПБ ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГ ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГ ')>0 OR instr(normalized,' САНКТПЕТЕРБУРГ ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГА ')>0 OR instr(normalized,' САНКТ ПЕТЕРБУРГА ')>0 OR instr(normalized,' САНКТПЕТЕРБУРГА ')>0 OR instr(normalized,' ПИТЕР ')>0) THEN 'SPB' WHEN (instr(normalized,' МОСКВА ')>0 OR instr(normalized,' МОСКВЫ ')>0 OR instr(normalized,' МСК ')>0) THEN 'MOSCOW' WHEN (instr(normalized,' ЕКБ ')>0 OR instr(normalized,' ЕКАТЕРИНБУРГ ')>0) THEN 'EKATERINBURG' WHEN (instr(normalized,' НОВОСИБ ')>0 OR instr(normalized,' НОВОСИБИРСК ')>0) THEN 'NOVOSIBIRSK' WHEN (instr(normalized,' КАЗАНЬ ')>0 OR instr(normalized,' КАЗАНИ ')>0) THEN 'KAZAN' WHEN (instr(normalized,' РОСТОВ ')>0 OR instr(normalized,' РОСТОВА ')>0) THEN 'ROSTOV' WHEN (instr(normalized,' КОСТРОМА ')>0 OR instr(normalized,' КОСТРОМЫ ')>0) THEN 'KOSTROMA' END END FROM city_name) city_key FROM av2_supplies;
--> statement-breakpoint
DROP VIEW av2_carton_city_scopes;
--> statement-breakpoint
CREATE VIEW av2_carton_city_scopes AS SELECT id,market,store,destination,(WITH RECURSIVE city_chars(rest,normalized) AS (
